import i18n from 'i18next'
import { initReactI18next } from 'react-i18next'

import enCommon from '@/assets/locales/en/common.json'
import enAuth from '@/assets/locales/en/auth.json'
import enShell from '@/assets/locales/en/shell.json'
import enProjects from '@/assets/locales/en/projects.json'
import enObjectives from '@/assets/locales/en/objectives.json'
import enAdmin from '@/assets/locales/en/admin.json'
import enMarketplace from '@/assets/locales/en/marketplace.json'

import deCommon from '@/assets/locales/de/common.json'
import deAuth from '@/assets/locales/de/auth.json'
import deShell from '@/assets/locales/de/shell.json'

import esCommon from '@/assets/locales/es/common.json'
import esAuth from '@/assets/locales/es/auth.json'
import esShell from '@/assets/locales/es/shell.json'

const defaultLocale = import.meta.env.VITE_DEFAULT_LOCALE ?? 'en'

i18n.use(initReactI18next).init({
  lng: defaultLocale,
  fallbackLng: 'en',
  defaultNS: 'common',
  resources: {
    en: {
      common: enCommon,
      auth: enAuth,
      shell: enShell,
      projects: enProjects,
      objectives: enObjectives,
      admin: enAdmin,
      marketplace: enMarketplace,
    },
    de: {
      common: deCommon,
      auth: deAuth,
      shell: deShell,
    },
    es: {
      common: esCommon,
      auth: esAuth,
      shell: esShell,
    },
  },
  interpolation: { escapeValue: false },
})

export default i18n
